-- One self-contained record following DocumentIngestSchema.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODEx7f911382bd05$doc_compensation_relating_to_torture_act_2053_1996__2053_1996-12-18_legal_govt-of-nepal_eng_pdf$CODEx7f911382bd05$,$CODEx0ab805da0f73$Compensation Relating to Torture Act, 2053 (1996)$CODEx0ab805da0f73$,NULL,$CODEx76f3b5a7170a$act$CODEx76f3b5a7170a$,2053,1996,5,$CODEx8184dc6fab17$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "www.lawcommission.gov.np \nwww.lawcommission.gov.np \n1\nCompensation Relating to Torture Act, 2053 (1996)  \n \n Date of Authentication and Publication  \n 2053-9-3 (18 Dec.1996) \nAct Number 14 of the year 2053 (1996) \nAn Act made to Provide for Compensation to the Pers on subjected to Torture \nwhile in Detention . \nPreamble : Whereas, it is expedient to make provisions on comp ensation for \ninflicting physical or mental torture upon any pers on in detention in the course of \ninvestigation, inquiry or trial or for any other re ason or for giving cruel, inhuman or \ndegrading treatment to such a person; \n Now, therefore, be it enacted by the Parliament in  the 25th year of reign of His \nMajesty King Birendra Bir Bikram Shah Dev .", "children": []}, {"tier": 1, "nodeType": "section_group", "identifier": "Sections", "title": "Sections", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short Title and Commencement : (1) This Act may be called as", "content": "\"Compensation Relating to Torture Act, 2053 (1996). \" \n(2) It shall come into force immediately.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definitions : Unless the subject or the context otherwise requi res, in this Act,-", "content": "(a) \"Torture\" means physical or mental torture infl icted upon a person in \ndetention in the course of investigation, inquiry o r trial or for any other \nreason and includes any cruel, inhuman or degrading  treatment given to \nhim/her. \n(b) \"Victim\" means any person upon whom torture is inflicted.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "Prohibition on Torture : (1) No person in detention in the course of", "content": "investigation, inquiry or trial or for any other re ason shall be subjected to \ntorture. \nwww.lawcommission.gov.np \nwww.lawcommission.gov.np \n2\nExplanation : For the purposes of this Sub-section, the words \" in \ndetention\" shall include the situation of being tak en into custody in accordance \nwith the prevailing law. \n(2) In detaining and releasing any person, the conc erned official shall \nget such person examined physically by a medical pr actitioner engaged in the \ngovernmental service as far as possible and him/her self examine such person in \ncases where no such medical practitioner is availab le, and maintain records \nthereof. \nExplanation : For the purposes of this sub-section, \"medical \npractitioner\" shall include a Doctor, Kabiraj (Senior Ayurvedic Practitioner), \nhealth assistant, assistant health worker or Vaidhaya  (Junior Ayurvedic \nPractitioner) . \n(3) One copy of the report on examination of physic al or mental \nsituation referred to in Sub-section (2) has to be sent to the concerned District \nCourt.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Provision of Compensation  : If any employee of Government of Nepal is held", "content": "to have inflicted torture upon any person, the vict im shall be provided with \ncompensation as referred to in this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Filing of Complaint  : (1) A victim may, within 35 days from the date o f", "content": "inflicting torture upon him/her or of his/her relea se from detention, file with \nthe District Court of the District, where he/she ha s been detained, a complaint \nmaking a claim for compensation. \n(2) Notwithstanding anything contained in Sub-secti on (1), in the event \nof death of a victim or failure of the victim for a ny other reason to file a \ncomplaint in person, any one of his/her family memb ers having attained the \nrequired age or his/her legal practitioner may, set ting out reasons therefor, file \na complaint under Sub-section (1). \n(3) Any one of the detainee's family members having  attained the \nrequired age or his/her legal practitioner may, if he/she thinks that torture has \nwww.lawcommission.gov.np \nwww.lawcommission.gov.np \n3\nbeen inflicted on the detainee, file a petition wit h the concerned District Court. \nIf such application is filed, the court may order f or physical or mental \nexamination of the person in detention within three  days. If, upon such \nexamination, it appears that his/her medical treatm ent is to be done, his/her \ntreatment shall be done on behalf of Government of Nepal. \n  (4) Any complaint to be filed under Sub-section ( 1) or (2) shall also \ncontain the following matters, as far as possible:- \n(a) Reason for detention and period of time spent i n \ndetention. \n(b) Description of torture inflicted while in deten tion. \n(c) Description of loss resulted from torture. \n(d) Amount of compensation claimed. \n(e) Any other details which may be ancillary to sub stantiate \nthe claim.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Proceedings on Complaint and Compensation", "content": ": (1) The District Court shall \nproceed with a complaint filed under Section 5 by f ollowing the procedures \nreferred to in the Summary Procedures Act, 2028 (19 72), and if the contents of \nsuch complaint are found to be true and correct, ma ke a decision requiring \nGovernment of Nepal to pay compensation in a sum no t exceeding One \nHundred Thousand Rupees to the victim. \n  (2) If, in the course of the proceedings under Su b-section (1), a \ncomplaint is held to have been made with mala fide  intention, the complainant \nmay be punished with a fine not exceeding Five Thousand Rupees.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Action against the Person Involved in the Commis sion of Torture : If it is", "content": "held that torture has been inflicted as mentioned i n this Act, the District Court \nmay order the concerned body to take departmental a ction against the \ngovernmental employee who has inflicted such tortur e, in accordance with the \nprevailing law. \nwww.lawcommission.gov.np \nwww.lawcommission.gov.np \n4", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Fixation of Amount of Compensation  : In fixing amount of compensation for", "content": "purposes of Sub-section (1) of Section 6, it has to  be fixed taking into account \nof the following matters :- \n(a) Physical or mental pain or suffering inflicted on the victim and its \ngravity. \n(b) Depreciation occurred in income-earning capacit y of the victim as a \nconsequence of physical or mental injury. \n(c) In the case of physical or mental injury of inc urable nature, the age of \nthe victim and his/her family obligation. \n(d) In the case of an injury of curable nature, est imated expenditure for its \ntreatment. \n(e) In the event of the death of the victim as a re sult of torture, number of \nhis/her family members dependent on his/her income and minimum \nexpenditure required for their livelihood. \n(c) The matters deemed proper and just, out of the matters claimed by the \nvictim.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Execution of the Decision", "content": ": (1) After the final decision on provision of \ncompensation to a victim, the victim or his/her nea rest heir, in the event of \nhis/her death, has to make an application, accompan ied by a copy of the \ndecision made by the District Court on provision of  compensation, to the Chief \nDistrict Officer of the District where the victim h as been detained, for having \namount of compensation within one year from the dat e of receipt of a notice of \nsuch decision. \n(2) The Chief District Officer has to provide the a mount of \ncompensation to the applicant within thirty five da ys of receipt of the \napplication referred to in Sub-section (1). \n(3) No amount of compensation shall be provided if any application is \nnot made within the time-limit referred to in Sub-section (1). \nwww.lawcommission.gov.np \nwww.lawcommission.gov.np \n5", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "Defense by Government Attorney  : The Government Attorney shall, if so", "content": "requested by the concerned Office In-charge, appear  in the Court on behalf of \nsuch employee and defend him/her on the complaint f iled under Section 5.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Not to Be Deemed Torture  : Notwithstanding anything contained elsewhere", "content": "in  this Act, any pain or suffering arising natural ly from being detained in \naccordance with the prevailing law shall not be dee med to be an act of torture \nfor the purposes of this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "No Restriction on Taking Action under Prevailin g Law : Nothing shall be", "content": "deemed to prevent the taking of separate action in such matter as may be \ndeemed to be an offence under the prevailing law on ly by virtue of the fact that \naction has been taken under this Act for compensati on for torture or that \ncompensation has been received.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "Power To Frame Rules  : Government of Nepal may frame necessary Rules in", "content": "order to carry out the objectives of this Act.", "children": []}]}]$CODEx8184dc6fab17$::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,"originalTitle"=EXCLUDED."originalTitle","documentType"=EXCLUDED."documentType","yearBs"=EXCLUDED."yearBs","yearAd"=EXCLUDED."yearAd","totalPages"=EXCLUDED."totalPages",nodes=EXCLUDED.nodes;
